from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import CommercialContract

class LocalizedContractTermsView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, contract_id, lang_code):
        field_name = f"terms_and_conditions_{lang_code}"
        # Restrict contract query to company of authenticated user
        contract_data = CommercialContract.objects.filter(
            id=contract_id,
            company=request.user.company
        ).values('id', 'counterparty_name', field_name).first()
        if not contract_data:
            return Response({"error": "Contract not found"}, status=status.HTTP_404_NOT_FOUND)

        return Response({"contract_id": contract_data['id'], "terms": contract_data.get(field_name)})
